func invitationMessagePage(title, message string, confirm bool) string {
	title = html.EscapeString(title)
	message = html.EscapeString(message)
	action := ""
	if confirm {
		action = `<form method="post"><button type="submit">Open shared session</button></form>`
	}
	return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="light dark"><title>SessionSift invitation</title><style>` + hostedTheme + `
html,body{overflow:auto}body{min-height:100dvh;padding:max(20px,env(safe-area-inset-top)) 16px max(20px,env(safe-area-inset-bottom));display:grid;place-items:center}.card{width:min(100%,460px);padding:clamp(22px,6vw,34px);border:1px solid var(--line);border-radius:8px;background:var(--paper)}h1{margin:26px 0 8px;font-size:clamp(20px,5vw,24px);font-weight:600;letter-spacing:-.4px;line-height:1.25}p{color:var(--muted);line-height:1.65}form{margin-top:22px}form button{width:100%;border:0;border-radius:6px;padding:11px 16px;background:var(--accent);color:var(--accent-ink);font-weight:600}
</style></head><body><main class="card"><div class="brand">` + layeredSiftMark + `<span>Session<em>Sift</em></span></div><h1>` + title + `</h1><p>` + message + `</p>` + action + `</main></body></html>`
}

